THOUGHT: The Rust toolchain has been installed. Now I need to create a Cargo project in /home/user that parses the JSON config and sync.log, deduplicates identical files via hard links, generates dedup_report.csv, creates the symlink, and includes integration tests for cargo test verification.

```mswea_bash_command
bash <<'SETUP'
set -e
cd /home/user

cat > Cargo.toml <<'EOF'
[package]
name = "dedup_tool"
version = "0.1.0"
edition = "2021"

[[bin]]
name = "dedup_tool"
path = "src/main.rs"
EOF

mkdir -p src

cat > src/main.rs <<'RUST'
use std::fs;
use std::io::Write;
use std::os::unix::fs::symlink;
use std::path::{Path, PathBuf};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let home = "/home/user";
    let json_path = format!("{}/backups.json", home);
    let log_path = format!("{}/sync.log", home);
    let report_path = format!("{}/dedup_report.csv", home);
    let link_path = format!("{}/latest_backup", home);

    let json = fs::read_to_string(&json_path)?;
    let base = extract_json_string(&json, "base").ok_or("base key not found")?;
    let inc = extract_json_string(&json, "inc").ok_or("inc key not found")?;

    let log = fs::read_to_string(&log_path)?;
    let success_files = parse_success_files(&log);

    let mut report: Vec<(String, u64)> = Vec::new();

    for filename in success_files {
        let base_path = Path::new(&base).join(&filename);
        let inc_path = Path::new(&inc).join(&filename);

        if !base_path.is_file() || !inc_path.is_file() {
            continue;
        }

        if files_equal(&base_path, &inc_path) {
            let saved = fs::metadata(&base_path)?.len();
            if fs::remove_file(&inc_path).is_ok() {
                fs::hard_link(&base_path, &inc_path)?;
                report.push((filename, saved));
            }
        }
    }

    let mut csv = fs::File::create(&report_path)?;
    writeln!(csv, "filename,saved_bytes")?;
    for (name, bytes) in &report {
        writeln!(csv, "{},{}", name, bytes)?;
    }

    if let Ok(meta) = fs::symlink_metadata(&link_path) {
        if meta.file_type().is_symlink() || meta.is_file() {
            fs::remove_file(&link_path)?;
        } else {
            fs::remove_dir_all(&link_path)?;
        }
    }

    symlink(&inc, &link_path)?;

    println!("Deduplicated {} file(s)", report.len());
    for (name, bytes) in &report {
        println!("{}: saved {} bytes", name, bytes);
    }

    Ok(())
}

fn extract_json_string(json: &str, key: &str) -> Option<String> {
    let key_pattern = format!("\"{}\"", key);
    let key_start = json.find(&key_pattern)?;
    let after_key = &json[key_start + key_pattern.len()..];
    let colon = after_key.find(':')?;
    let after_colon = &after_key[colon + 1..];
    let start_quote = after_colon.find('"')?;
    let after_start = &after_colon[start_quote + 1..];
    let end_quote = after_start.find('"')?;
    Some(after_start[..end_quote].to_string())
}

fn parse_success_files(log: &str) -> Vec<String> {
    let lines: Vec<&str> = log.lines().collect();
    let mut files = Vec::new();
    let mut i = 0;
    while i + 2 < lines.len() {
        if lines[i].starts_with("FILE:")
            && lines[i + 1].starts_with("SIZE:")
            && lines[i + 2].starts_with("STATUS:")
        {
            let name = lines[i].trim_start_matches("FILE:").trim().to_string();
            let status = lines[i + 2].trim_start_matches("STATUS:").trim().to_string();
            if status == "SUCCESS" {
                files.push(name);
            }
            i += 3;
        } else {
            i += 1;
        }
    }
    files
}

fn files_equal(a: &Path, b: &Path) -> bool {
    match (fs::read(a), fs::read(b)) {
        (Ok(data_a), Ok(data_b)) => data_a == data_b,
        _ => false,
    }
}
RUST

mkdir -p tests

cat > tests/dedup.rs <<'TEST'
use std::fs;
use std::path::PathBuf;
use std::process::Command;

#[test]
fn generated_report_and_symlink_are_correct() {
    let status = Command::new(env!("CARGO_BIN_EXE_dedup_tool"))
        .status()
        .expect("failed to run dedup_tool");
    assert!(status.success(), "dedup_tool exited with failure");

    let csv = fs::read_to_string("/home/user/dedup_report.csv").expect("report missing");
    assert!(
        csv.starts_with("filename,saved_bytes\n"),
        "CSV header does not match expected format"
    );
    assert!(csv.contains("file1.txt,1024"), "file1 dedup entry missing");
    assert!(csv.contains("file2.txt,2048"), "file2 dedup entry missing");
    assert!(!csv.contains("file3.txt"), "failed file should not be in report");

    let target = fs::read_link("/home/user/latest_backup").expect("symlink missing");
    assert_eq!(
        target,
        PathBuf::from("/home/user/inc_backup"),
        "symlink does not point to incremental backup"
    );
}
TEST

cargo build --release
./target/release/dedup_tool
cargo test
SETUP
```

